    for (int n = 5; n > 0; n--) {
        cout << n << " ";
    }
    cout << "FIRE!" << endl;
    return 0;
}

int n, total = 0;
cout << "Sampai berapa? ";
cin >> n;
for (int i = 1; i <= n; i++) {
    total += i;          // total = total + i
}
cout << "Jumlah 1.." << n << " = " << total;

