#include <iostream>
using namespace std;

int main() {
    int x = 5;
    for (int i = 1; i <= x; i++) {        // baris
        for (int j = 1; j <= i; j++) {    // isi baris ke-i
            cout << "*";
        }
        cout << endl;                     // pindah baris
    }
    return 0;
}

for (int i = 1; i <= 5; i++) {
    for (int j = 1; j <= 5; j++) {
        cout << i * j << "\t";
    }
    cout << endl;
}
